//! Implementation of the contract entry point (ABI §2), called by the exported functions generated by
//! [`crate::entry!`]; the native mock host goes through the same path.

use alloc::vec::Vec;

use crate::codec::{decode_call_input, encode, CallResult};

/// Revert reason when the input is not a valid Borsh `(String, Vec<u8>)` (never happens when the VM calls per the ABI).
pub const ERR_MALFORMED_INPUT: &[u8] = b"malformed call input";

/// Decodes the input `(method, args)`, calls `dispatch`, and Borsh-encodes the result as `Result<Vec<u8>, Vec<u8>>`.
///
/// The output is encoded with `borsh` itself (tag 1 for `Ok`, 0 for `Err`), matching the VM's decoding with
/// `borsh::from_slice`.
pub fn run<F>(input: &[u8], dispatch: F) -> Vec<u8>
where
    F: FnOnce(&str, &[u8]) -> CallResult,
{
    let result: CallResult = match decode_call_input(input) {
        Some((method, args)) => dispatch(method, args),
        None => Err(ERR_MALFORMED_INPUT.to_vec()),
    };
    encode(&result)
}

#[cfg(target_arch = "wasm32")]
pub use crate::wasm::{ksana_alloc, ksana_call};

/// Generates the contract entry point: exports `ksana_alloc(len: i32) -> i32` and
/// `ksana_call(ptr: i32, len: i32) -> i64` (ABI §2).
///
/// The argument is the dispatch function (`fn(&str, &[u8]) -> CallResult`): it receives the method name and argument
/// bytes and returns `Ok(data)` or `Err(reason)` (revert). The exported functions are only generated on wasm32; native
/// tests register the dispatch function directly with [`mock`](crate::mock).
///
/// ```ignore
/// ksana_contract_sdk::entry!(dispatch);
///
/// pub fn dispatch(method: &str, args: &[u8]) -> ksana_contract_sdk::CallResult {
///     match method {
///         "init" => ksana_contract_sdk::ok(&()),
///         _ => ksana_contract_sdk::revert("unknown method"),
///     }
/// }
/// ```
#[macro_export]
macro_rules! entry {
    ($dispatch:expr) => {
        /// ABI §2: the VM calls it to allocate a `len`-byte buffer (for the input and the variable-length data returned
        /// by host functions).
        #[cfg(target_arch = "wasm32")]
        #[allow(unsafe_code)]
        #[no_mangle]
        pub extern "C" fn ksana_alloc(len: i32) -> i32 {
            $crate::entry::ksana_alloc(len)
        }

        /// ABI §2: the contract entry point. The input is Borsh `(method, args)`; returns the packed output pointer and
        /// length.
        #[cfg(target_arch = "wasm32")]
        #[allow(unsafe_code)]
        #[no_mangle]
        pub extern "C" fn ksana_call(ptr: i32, len: i32) -> i64 {
            $crate::entry::ksana_call(ptr, len, $dispatch)
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::string::String;
    use alloc::vec;

    fn echo(method: &str, args: &[u8]) -> CallResult {
        match method {
            "ok" => Ok(args.to_vec()),
            _ => Err(method.as_bytes().to_vec()),
        }
    }

    #[test]
    fn output_is_borsh_result() {
        let input = borsh::to_vec(&(String::from("ok"), vec![9u8, 8])).unwrap();
        let out = run(&input, echo);
        // Borsh: the Ok tag is 1.
        assert_eq!(out, vec![1, 2, 0, 0, 0, 9, 8]);
        assert_eq!(
            borsh::from_slice::<Result<Vec<u8>, Vec<u8>>>(&out).unwrap(),
            Ok(vec![9, 8])
        );

        let input = borsh::to_vec(&(String::from("no"), Vec::<u8>::new())).unwrap();
        let out = run(&input, echo);
        // Borsh: the Err tag is 0.
        assert_eq!(out, vec![0, 2, 0, 0, 0, b'n', b'o']);
        assert_eq!(
            borsh::from_slice::<Result<Vec<u8>, Vec<u8>>>(&out).unwrap(),
            Err(b"no".to_vec())
        );
    }

    #[test]
    fn malformed_input_reverts_without_dispatch() {
        let out = run(&[1, 2, 3], |_, _| panic!("must not dispatch"));
        assert_eq!(
            borsh::from_slice::<Result<Vec<u8>, Vec<u8>>>(&out).unwrap(),
            Err(ERR_MALFORMED_INPUT.to_vec())
        );
    }
}
